<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {damageCalculation,weaponMechanics} from '../../../api/src/rules/combat-damage';
import {api,ApiError} from '../lib/api';
const props=defineProps<{campaignId:string;room:any}>(),emit=defineEmits<{changed:[]}>();
const endpoint=`/api/campaigns/${props.campaignId}/combat`,pending=ref<any[]>([]),error=ref(''),busy=ref(false),request=ref<any>(null);
const attackEdge=ref(false);
const weapons=ref<any[]>([]),weaponId=ref('');
const attackers=ref<any[]>([]),attackerId=ref(''),optionId=ref(''),attackTarget=ref(''),attackBonus=ref(0),attackDamageBonus=ref(0),attackSurprise=ref(false),category=ref(''),weaponSearch=ref('');
const attacker=computed(()=>attackers.value.find(a=>a.id===attackerId.value));
const categories=computed(()=>[...new Set<string>((attacker.value?.options??[]).map((w:any)=>w.group??'Autres'))].sort((a,b)=>a.localeCompare(b,'fr')));
const options=computed(()=>(attacker.value?.options??[]).filter((w:any)=>(!category.value||w.group===category.value)&&w.label.toLocaleLowerCase('fr').includes(weaponSearch.value.toLocaleLowerCase('fr'))));
const option=computed(()=>attacker.value?.options.find((o:any)=>o.id===optionId.value));
watch(attackerId,()=>{attackEdge.value=false;optionId.value='';category.value='';weaponSearch.value='';});

const eventId=ref(''),targetId=ref(''),damage=ref<number|null>(null),bonusDamage=ref(0),penetration=ref(0),damageType=ref('melee'),attackMode=ref('melee'),surprise=ref(false);
const drafts=ref<Record<string,any>>({});let alive=true,timer:ReturnType<typeof setInterval>;
const rolls=computed(()=>props.room.events.filter((e:any)=>['roll','gm-roll'].includes(e.kind)&&e.payload.total!==undefined));
const targets=computed(()=>[...props.room.characters,...props.room.combatants]);
watch(weaponId,()=>{const w=weapons.value.find(w=>w.id===weaponId.value);if(w){damage.value=w.damage;penetration.value=Number(/Perforant\s+(\d+)/i.exec(w.properties)?.[1]??0);damageType.value=weaponMechanics(w).damageType;attackMode.value=weaponMechanics(w).attackMode;}});
watch(eventId,()=>{const p=rolls.value.find((e:any)=>e.id===eventId.value)?.payload;damage.value=p?.damage??null;penetration.value=p?.penetration??0;damageType.value=p?.damageType??'melee';attackMode.value=p?.attackMode??(p?.damageType==='balistique'?'ranged':'melee');});
async function load(){if(!alive||document.visibilityState==='hidden')return;try{const r=await api<any>(endpoint);if(!alive)return;pending.value=r.pending;weapons.value=r.weapons??[];attackers.value=r.attackers??[];if(!attackers.value.some(a=>a.id===attackerId.value)&&attackers.value.length)attackerId.value=attackers.value[0].id;for(const a of r.pending)drafts.value[a.id]??={protectionIds:[],material:['melee','balistique','antichoc'].includes(a.damageType),armor:a.target.armor,extraArmor:0,extraReduction:0,bonus:0,defenseOverride:0,edge:false,defensePowerId:''};}catch{if(alive){pending.value=[];error.value='Impossible de charger les attaques en attente.';}}}
async function send(action:string,extra:any){if(busy.value)return;if(request.value){error.value='Réessaie l’action non confirmée.';return;}request.value={action,requestId:crypto.randomUUID(),...extra};await retry();}
async function retry(){if(busy.value||!request.value)return;busy.value=true;error.value='';try{await api(endpoint,{method:'POST',body:JSON.stringify(request.value)});request.value=null;attackEdge.value=false;await load();emit('changed');}catch(e){error.value=e instanceof ApiError&&e.status===409?'Cette attaque a déjà changé ou a déjà été traitée.':e instanceof ApiError&&e.message==='insufficient_edge'?'Pas assez d’Edge pour cette dépense.':e instanceof ApiError&&e.message==='defense_power_unavailable'?'Cette défense spéciale est indisponible ou déjà utilisée. Actualise et choisis une autre défense.':e instanceof ApiError&&e.message==='active_defense_unavailable'?'Défense active indisponible : vérifie les PA, l’initiative, la surprise et les blessures.':e instanceof ApiError&&e.message==='attack_unavailable'?'Attaque indisponible : commence le combat, vérifie les PA et les blessures.':'Action non confirmée. Réessaie.';if(e instanceof ApiError&&e.status<500){request.value=null;await load();}}finally{busy.value=false;}}
function specialDefense(a:any){return a.target.specialDefenses?.find((p:any)=>p.id===drafts.value[a.id]?.defensePowerId);}
function canDefend(a:any){return drafts.value[a.id]?.defensePowerId?specialDefense(a)?.available:a.target.canDefend&&!a.surprise&&!a.narrativeFailure;}
function preview(a:any){const d=drafts.value[a.id],items=a.target.protections.filter((p:any)=>d.protectionIds.includes(p.id)),defense=a.defense?.narrativeFailure?d.defenseOverride:a.defense?.total??a.target.defense;
 const armor=!d.material?0:Number(d.armor)+Number(d.extraArmor)+Math.max(0,...items.map((p:any)=>p.armor))+Math.max(a.target.bodyArmor??0,...items.map((p:any)=>p.body)),reduction=Number(d.extraReduction)+(a.target.reductions?.[a.damageType]??0)+Math.max(0,...items.map((p:any)=>p.reductions[a.damageType]??0)),margin=Math.max(0,a.total-defense),material=Math.max(0,armor-a.penetration);
 return damageCalculation(a,defense,armor,reduction);
}
async function prepareAttack(id:string,rollId=''){category.value='';weaponSearch.value='';attackerId.value=id;await nextTick();optionId.value=attacker.value?.options.some((o:any)=>o.id===rollId)?rollId:'';document.querySelector('.combat-resolution')?.scrollIntoView({behavior:'smooth',block:'start'});}
defineExpose({prepareAttack});
onMounted(()=>{void load();timer=setInterval(()=>void load(),3000);});onUnmounted(()=>{alive=false;clearInterval(timer);});
</script>
<template>
<section class="combat-resolution" aria-label="Résolution des attaques">
 <h2>Attaques & défenses</h2><p v-if="error" role="alert">{{ error }} <button v-if="request" :disabled="busy" @click="retry">Réessayer cette action</button></p>
 <p v-if="attacker&&!attacker.options.length">Aucune attaque chiffrée disponible : complète le profil de cette créature avant de lancer une attaque.</p><form v-if="attackers.length" @submit.prevent="send('launch',{attackerId,optionId,targetId:attackTarget,bonus:attackBonus,bonusDamage:attackDamageBonus,surprise:attackSurprise,...(attackEdge?{edge:true}:{})})"><h3>Lancer une attaque</h3><p v-if="attacker?.ready===false" role="status">{{attacker.initiativePending?'Lance d’abord ton initiative.':'Aucune attaque disponible : vérifie les PA, les blessures et la transformation en cours.'}}</p><div class="combat-fields"><label>Attaquant<select v-model="attackerId" aria-label="Attaquant" required><option v-for="a in attackers" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Catégorie d’arme<select v-model="category" aria-label="Catégorie d’arme"><option value="">Toutes les catégories</option><option v-for="c in categories" :key="c" :value="c">{{c}}</option></select></label><label>Rechercher une arme<input v-model="weaponSearch" type="search" /></label><label>Arme / attaque<select v-model="optionId" aria-label="Arme / attaque" required><option value="">Choisir…</option><optgroup v-for="group in categories.filter(c=>options.some((o:any)=>(o.group??'Autres')===c))" :key="group" :label="group"><option v-for="w in options.filter((o:any)=>(o.group??'Autres')===group)" :key="w.id" :value="w.id">{{w.label}} · DGT {{w.damage}}</option></optgroup></select></label><label>Cible de l’attaque<select v-model="attackTarget" aria-label="Cible de l’attaque" required><option value="">Choisir avant de lancer…</option><option v-for="t in targets.filter((t:any)=>t.id!==attackerId)" :key="t.id" :value="t.id">{{t.name}} · {{t.health}}</option></select></label><label>Bonus au jet<input v-model.number="attackBonus" type="number" min="-100" max="100" /></label><label>Bonus aux dégâts<input v-model.number="attackDamageBonus" type="number" min="-100" max="100" /></label><label v-if="attacker?.edge!=null" class="check"><input v-model="attackEdge" type="checkbox" :disabled="busy||attacker.edge<1" /> Forcer le Destin · 1 Edge ({{attacker.edge}} disponibles)</label><label class="check"><input v-model="attackSurprise" type="checkbox" /> Cible surprise</label></div><p v-if="option"><template v-if="option.components?.attributeName">{{option.components.attributeName}} {{option.components.attribute}} + {{option.components.skillName}} {{option.components.rank}} + bonus de fiche {{option.components.bonus??0}}</template><template v-else>Score du profil {{option.modifier}}</template> + bonus {{attackBonus}} + {{attackEdge?'20 (Edge)':'d10'}} · {{option.damage}} dégâts de base · {{option.penetration}} perforant</p><button :disabled="busy||attacker?.ready===false||!option||!attackTarget">Lancer l’attaque · 1 PA</button><small>{{room.canManage?'Catalogue trié par catégorie et par nom.':'Seules les armes de ton inventaire et tes attaques naturelles sont proposées.'}} La cible reçoit directement la demande de défense.</small></form>
 <details v-if="room.canManage"><summary>Diriger un jet d’attaque vers une cible</summary><form @submit.prevent="send('attack',{eventId,targetId,damage,bonusDamage,penetration,damageType,attackMode,surprise})"><div class="combat-fields">
 <label>Jet d’attaque<select v-model="eventId" required><option value="">Choisir un jet du journal…</option><option v-for="e in rolls" :key="e.id" :value="e.id">{{ e.characterName??e.payload.characterName??'MJ' }} · {{ e.payload.label }} → {{ e.payload.total }}</option></select></label>
 <label>Cible<select v-model="targetId" required><option value="">Choisir…</option><option v-for="c in targets" :key="c.id" :value="c.id">{{ c.name }}</option></select></label>
 <label>Arme du catalogue (facultatif)<select v-model="weaponId"><option value="">Profil du jet ou saisie</option><option v-for="w in weapons" :key="w.id" :value="w.id">{{ w.name }} · DGT {{ w.damage }}</option></select></label><label>Dégâts de l’arme<input v-model.number="damage" type="number" min="0" max="100" required /></label><label>Bonus de dégâts<input v-model.number="bonusDamage" type="number" min="-100" max="100" required /></label><label>Perforant<input v-model.number="penetration" type="number" min="0" max="100" required /></label><label>Calcul des dégâts<select v-model="attackMode" aria-label="Calcul des dégâts"><option value="melee">Mêlée / Pugilat · marge + DGT</option><option value="ranged">Tir · paliers de marge</option><option value="fixed">DGT fixes · effet particulier</option></select></label><label>Type de dégâts<select v-model="damageType"><option value="melee">Mêlée</option><option value="balistique">Balistique</option><option value="antichoc">Antichoc</option><option value="feu">Feu</option><option value="froid">Froid</option><option value="electricite">Électricité</option><option value="chimique">Chimique</option><option value="occulte">Occulte</option><option value="neuro">Neuro</option></select></label>
 <label class="check"><input v-model="surprise" type="checkbox" /> Surprise : pas de défense active</label></div><button :disabled="busy||!eventId||!targetId||damage===null">Proposer l’attaque au défenseur</button><small>Vérifie les propriétés de l’arme et les bonus de dégâts avant d’envoyer. Le joueur ciblé peut choisir sa défense ici ; le MJ peut aussi la résoudre.</small></form></details>
 <p v-if="!pending.length">Aucune attaque en attente de défense.</p>
 <article v-for="a in pending" :key="a.id" class="pending-attack"><h3>{{ a.attacker }} → {{ a.target.name }} · Attaque {{ a.total }}</h3><p>DGT {{ a.damage }} + bonus {{ a.bonusDamage }} · {{ a.damageType }} · Perforant {{ a.penetration }}</p><strong v-if="a.narrativeFailure">Échec narratif de l’attaque : aucun dégât.</strong>
 <div v-if="!a.defense" class="combat-fields"><label v-if="a.target.specialDefenses?.length">Capacité de défense<select v-model="drafts[a.id].defensePowerId" :aria-label="`Capacité de défense de ${a.target.name}`"><option value="">Défense ordinaire · 1 PA</option><option v-for="p in a.target.specialDefenses" :key="p.id" :value="p.id" :disabled="!p.available">{{p.name}} · {{p.cost}} PA · +{{p.bonus}} · 1/{{p.limit==='round'?'round':'scène'}}{{p.used?' · déjà utilisée':''}}{{p.surprise?' · même Surpris':''}}</option></select></label><p v-if="specialDefense(a)">{{specialDefense(a).name}} : +{{specialDefense(a).bonus}} appliqué automatiquement. L’usage est consommé au lancer, même en cas d’échec narratif. {{specialDefense(a).surprise?'La Surprise n’interdit pas cette réaction.':'Ne permet pas de réagir en Surprise.'}}</p><label>Bonus de défense<input v-model.number="drafts[a.id].bonus" type="number" min="-100" max="100" /></label><button :disabled="busy" @click="send('defend',{attackId:a.id,active:false,bonus:drafts[a.id].bonus})">Défense passive · 0 PA</button><button :disabled="busy||!canDefend(a)" @click="send('defend',{attackId:a.id,active:true,bonus:drafts[a.id].bonus,...(drafts[a.id].defensePowerId?{defensePowerId:drafts[a.id].defensePowerId}:{}),...(drafts[a.id].edge?{edge:true}:{})})">Défense active · {{specialDefense(a)?.cost??1}} PA · {{drafts[a.id].edge?'20 (Edge)':'d10'}}</button><label v-if="a.target.edge!=null" class="check"><input v-model="drafts[a.id].edge" type="checkbox" :disabled="busy||a.target.edge<1" /> Forcer la défense active · 1 Edge ({{a.target.edge}} disponibles)</label><span>{{ a.target.pa }} PA disponibles</span></div>
 <form v-else @submit.prevent="send('resolve',{attackId:a.id,...drafts[a.id]})"><p v-if="a.defense.defensePowerName">{{a.defense.defensePowerName}} · {{a.defense.paCost}} PA · bonus automatique +{{a.defense.components?.specialBonus}}</p><p>{{ a.defense.label }} : {{ a.defense.modifier }}<template v-if="a.defense.dice"> + {{ a.defense.dice.join(' + ') }}</template> = {{ a.defense.total }}</p>
 <p v-if="a.defense.narrativeFailure" role="alert">Échec narratif de la défense : le MJ doit arbitrer la défense retenue avant application.</p><label v-if="a.defense.narrativeFailure&&room.canManage">Défense retenue après arbitrage<input v-model.number="drafts[a.id].defenseOverride" type="number" min="0" max="1000" required /></label>
 <fieldset><legend>Protections applicables à cet impact</legend><label class="check"><input v-model="drafts[a.id].material" type="checkbox" /> La protection matérielle peut s’interposer contre cet impact</label><p v-if="a.target.bodyArmor">Armure corporelle de la forme : {{a.target.bodyArmor}} (meilleure protection corporelle retenue).</p><p v-if="a.target.reductions?.[a.damageType]">Réduction du profil : {{ a.target.reductions[a.damageType] }}</p><label v-for="p in a.target.protections" :key="p.id" class="check"><input v-model="drafts[a.id].protectionIds" type="checkbox" :value="p.id" /> {{ p.name }} — {{ p.text }}</label><div class="combat-fields"><label>Armure du profil<input v-model.number="drafts[a.id].armor" type="number" min="0" max="100" required /></label><label>Armure supplémentaire applicable<input v-model.number="drafts[a.id].extraArmor" type="number" min="0" max="100" required /></label><label>Réduction supplémentaire applicable<input v-model.number="drafts[a.id].extraReduction" type="number" min="0" max="100" required /></label></div><small>Coche seulement les protections portées et applicables. Meilleure armure portée + meilleure armure corporelle ; pas de double cumul. Ajuste les effets conditionnels, pouvoirs, charges ablatives ou protections spéciales d’après leur texte. La protection matérielle est proposée pour les dégâts physiques ; confirme sa pertinence pour les effets particuliers.</small></fieldset>
 <p class="damage-preview"><template v-if="preview(a).attackMode==='melee'">Marge {{ preview(a).margin }} + arme {{ a.damage }}</template><template v-else>{{preview(a).multiplier}} × arme {{a.damage}} (marge {{preview(a).margin}})</template> + bonus {{ a.bonusDamage }} − protection matérielle {{ preview(a).material }} − réduction {{ preview(a).reduction }} = <strong>{{ preview(a).damage }} dégâts</strong></p><p v-if="preview(a).alteration">Une Altération cohérente est à déterminer avec le MJ.</p><button :disabled="busy||(a.defense.narrativeFailure&&!room.canManage)">Appliquer {{ preview(a).damage }} dégâts aux PV</button></form>
 <button v-if="room.canManage" :disabled="busy" @click="send('cancel',{attackId:a.id})">Annuler cette attaque</button></article>
</section>
</template>
<style scoped>
.combat-resolution{padding:16px;margin:0 0 24px;background:#0d1b2b;border:1px solid #355267;border-radius:8px;min-width:0}.combat-fields{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.combat-fields label{flex:1;min-width:130px}.combat-resolution label{display:grid;gap:6px;margin:10px 0}.combat-resolution .check{display:flex;align-items:center}.combat-resolution input:not([type=checkbox]),.combat-resolution select{box-sizing:border-box;width:100%;min-width:0;padding:10px;background:#08131f;color:#e6eef8;border:1px solid #526c80;border-radius:5px;font:inherit}.combat-resolution button{padding:10px;min-height:44px;margin:5px;background:#143247;color:#d5f6ff;border:1px solid #52758b;border-radius:5px;cursor:pointer}.combat-resolution button:disabled{opacity:.5;cursor:default}.combat-resolution summary{padding:12px;cursor:pointer}.combat-resolution fieldset{min-width:0;border:1px solid #355267}.pending-attack{padding:12px;border:1px solid #52758b;border-radius:6px;margin:12px 0}.combat-resolution small{display:block;color:#b7c9d6;line-height:1.5}.damage-preview{color:#b7efff}
</style>
